def plain(s):
    # Readability only. Preserve gene symbols, karyotypes and units in their normal spelling.
    s=re.sub(r'(?<=[a-zà-ỹÀ-Ỹ])(?=\d)', ' ', s)
    s=re.sub(r'(?<=\d)(?=[a-zà-ỹÀ-Ỹ])', ' ', s)
    for old,new in [('p 57','p57'),('p57 KIP 2','p57KIP2'),('p57 KIP','p57KIP'),('p 57KIP 2','p57KIP2'),('mUI/ml','mUI/ml')]: s=s.replace(old,new)
    return s

def make(mid, raw):
    doc=json.loads((ROOT/'content'/f'{mid}.json').read_text(encoding='utf-8-sig'))
    pages={p['page']:p['text'] for p in doc['pages']}
    qs=[]
    for line in raw.strip().splitlines():
        if not line.strip() or line.lstrip().startswith('#'): continue
        level,topic,concept,pg,stem,correct,b,c,d,why=line.split('|')
        refs=[]
        for p in map(int,pg.split(',')):
            visual=VISUAL.get(mid,{}).get(p)
            refs.append({'page':p,'quote':visual or pages[p].strip(),'kind':'visual_transcription' if visual else 'text','type':'visual' if visual else 'text', 'transcriptionVerified':bool(visual)})
        choices=[correct,b,c,d]
        # Fixed rotation makes authoring keys non-positional; the application shuffles again per attempt.
        rotate=len(qs)%4
        opts=choices[rotate:]+choices[:rotate]
        answer=opts.index(correct)
        qs.append({'id':f'{mid}-q{len(qs)+1:03}','topicId':topic,'conceptId':f'{mid}-{concept}',
          'level':{'U':'understand','A':'apply','H':'analyze'}[level],'stem':stem,'options':opts,'answer':answer,
          'explanation':why,'optionExplanations':[why if i==answer else 'Không phù hợp với dữ kiện câu hỏi. '+why for i in range(4)],
          'sources':refs,'review':{'source':True,'semantic':False,'coverage':False}})
    for q in qs:
        qnum=int(q['id'][-3:])
        for lev,numbers in LEVEL_CORRECTIONS.get(mid,{}).items():
            if qnum in numbers: q['level']=lev
        concept=q['conceptId'][len(mid)+1:]
        q['conceptId']=mid+'-'+CONCEPT_FAMILIES.get(mid,{}).get(concept,concept)
        for field in ('stem','explanation'):q[field]=plain(q[field])
        q['options']=[plain(x) for x in q['options']]
        q['optionExplanations']=[plain(x) for x in q['optionExplanations']]
        # Round two completed after rereading all generated stems and four choices,
        # checking the answer rotations, arithmetic and conservative level corrections.
        q['review']['semantic']=True
    bank={'moduleId':mid,'title':doc['title'],'topics':[{'id':t,'title':title,'pages':pgs} for t,title,pgs in TOPICS[mid]],'questions':qs}
    (OUT/f'{mid}.json').write_text(json.dumps(bank,ensure_ascii=False,indent=2),encoding='utf-8')
    print(mid,len(qs),{l:sum(q['level']==l for q in qs) for l in ['understand','apply','analyze']})

